INSERT IGNORE INTO `subcategories` (`category_id`, `name`, `name_en`, `slug`) SELECT c.`id`, 'Ментальне здоров''я', 'Mental Health', 'mental-health' FROM `categories` c WHERE c.`slug` = 'health-beauty' LIMIT 1;
