SET @uid = (SELECT `id` FROM `users` WHERE `email` = 'whitevelvetelf@gmail.com' LIMIT 1);

-- Wysa — Ментальне здоров'я
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'wysa.com' OR LOWER(`name`) = LOWER('Wysa'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Wysa', NULL, 'https://www.wysa.com', NULL, NULL, 'Анонімний AI-помічник для ментального здоров''я на основі доказових підходів: самодопомога, супровід між сесіями з терапевтом і програми для організацій.', 'An anonymous AI mental health companion based on evidence-based approaches: self-help, support between therapy sessions and programmes for organisations.', 'Wysa — AI-помічник для ментального здоров''я, створений як безпечна й доказова альтернатива звичайним чат-ботам. Розмова повністю анонімна, без стигми й обмежень у часі: Wysa допомагає впоратися з тривогою, стресом і поганим настроєм за допомогою вправ і технік на основі доказових підходів. Сервіс підтримує людину на всіх етапах — від першого кроку й самодопомоги до спрямування до фахівця та супроводу між сесіями з терапевтом. Компанія співпрацює з роботодавцями, страховими компаніями та системами охорони здоров''я, які впроваджують Wysa у власні моделі допомоги. Wysa не замінює професійну допомогу в кризовій ситуації. Ціни для організацій — за запитом.', 'Wysa is an AI mental health companion built as a safe, evidence-based alternative to general chatbots. Conversations are completely anonymous, without stigma or time limits: Wysa helps you deal with anxiety, stress and low mood through exercises and techniques grounded in evidence-based approaches. It supports people at every stage — from the first step and self-help to referral to a professional and support between therapy sessions. The company works with employers, insurers and health systems that build Wysa into their care models. Wysa does not replace professional help in a crisis. Pricing for organisations is on request.', 'Анонімні розмови без обмежень у часі
Вправи на основі доказових підходів
Супровід між сесіями з терапевтом
Програми для роботодавців і систем охорони здоров''я', 'Anonymous conversations with no time limits
Exercises based on evidence-based approaches
Support between therapy sessions
Programmes for employers and health systems', 'Люди, які хочуть підтримати свій емоційний стан, а також роботодавці й медичні організації.', 'People who want to look after their emotional wellbeing, plus employers and healthcare organisations.', 'mobile', 'none', 'published', 0, 'found', @uid, '2026-10-01 00:00:00' FROM DUAL WHERE @new = 1;
SET @pid = (SELECT `id` FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'wysa.com' OR LOWER(`name`) = LOWER('Wysa')) ORDER BY `id` LIMIT 1);
