INSERT IGNORE INTO `product_translations` (`product_id`, `field_name`, `lang`, `translated_text`, `source`) SELECT @pid, 'full_description', 'en', 'Wysa is an AI mental health companion built as a safe, evidence-based alternative to general chatbots. Conversations are completely anonymous, without stigma or time limits: Wysa helps you deal with anxiety, stress and low mood through exercises and techniques grounded in evidence-based approaches. It supports people at every stage — from the first step and self-help to referral to a professional and support between therapy sessions. The company works with employers, insurers and health systems that build Wysa into their care models. Wysa does not replace professional help in a crisis. Pricing for organisations is on request.', 'manual' FROM DUAL WHERE @new = 1;
