-- Headspace — Ментальне здоров'я
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'headspace.com' OR LOWER(`name`) = LOWER('Headspace'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Headspace', NULL, 'https://www.headspace.com', NULL, NULL, 'Застосунок для медитацій і ментального здоров''я з AI-компаньйоном Ebb, який вислуховує голосом чи текстом і підбирає медитації та вправи саме для вас.', 'A meditation and mental health app with Ebb, an AI companion that listens by voice or text and suggests meditations and exercises just for you.', 'Headspace — один із найвідоміших застосунків для медитацій, сну й зниження стресу. Його AI-компаньйон Ebb допомагає активно рефлексувати: з ним можна говорити голосом або писати, він пам''ятає попередні розмови, розуміє, що з вами відбувається, і пропонує відповідні медитації та вправи з бібліотеки Headspace. Ebb доступний цілодобово, має вбудовані захисні механізми й за потреби спрямовує до кризових служб. Зараз Ebb доступний платним учасникам 18+ у США, Великій Британії, Канаді й Австралії англійською мовою. Підписка оформлюється помісячно або на рік, є сімейний план і 14-денний безкоштовний пробний період.', 'Headspace is one of the best-known apps for meditation, sleep and stress relief. Its AI companion Ebb helps you actively self-reflect: you can talk to it by voice or text, it remembers previous conversations, understands what you are going through and suggests suitable meditations and activities from the Headspace library. Ebb is available 24/7, has built-in safeguards and connects you to crisis support when needed. Ebb is currently available to paid members aged 18+ in the US, UK, Canada and Australia in English. Subscriptions are monthly or annual, with a family plan and a 14-day free trial.', 'AI-компаньйон Ebb (голос або текст)
Персональні добірки медитацій і вправ
Медитації, сон і зниження стресу
Сімейний план', 'Ebb AI companion (voice or text)
Personalised meditations and activities
Meditation, sleep and stress relief
Family plan', 'Люди, які хочуть менше стресу й кращий сон і шукають регулярну практику медитації.', 'People who want less stress and better sleep and are looking for a regular meditation practice.', 'web,mobile', 'none', 'published', 0, 'found', @uid, '2026-10-01 00:00:00' FROM DUAL WHERE @new = 1;
