INSERT IGNORE INTO `product_translations` (`product_id`, `field_name`, `lang`, `translated_text`, `source`) SELECT @pid, 'full_description', 'en', 'Headspace is one of the best-known apps for meditation, sleep and stress relief. Its AI companion Ebb helps you actively self-reflect: you can talk to it by voice or text, it remembers previous conversations, understands what you are going through and suggests suitable meditations and activities from the Headspace library. Ebb is available 24/7, has built-in safeguards and connects you to crisis support when needed. Ebb is currently available to paid members aged 18+ in the US, UK, Canada and Australia in English. Subscriptions are monthly or annual, with a family plan and a 14-day free trial.', 'manual' FROM DUAL WHERE @new = 1;
