-- Rosebud — Ментальне здоров'я
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'rosebud.app' OR LOWER(`name`) = LOWER('Rosebud'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Rosebud', NULL, 'https://www.rosebud.app', NULL, NULL, 'AI-щоденник для особистого розвитку: допомагає проговорити емоції, помічає закономірності у ваших записах і підтримує звички.', 'An AI journal for personal growth: it helps you process emotions, spots patterns in your entries and supports your habits.', 'Rosebud поєднує ведення щоденника, формування звичок і емоційну підтримку. Ви пишете або надиктовуєте думки, а AI ставить уточнювальні запитання, допомагає розібратися в емоціях, пам''ятає попередні записи та знаходить у них закономірності й нові інсайти про вас. Дані шифруються під час передачі та зберігання. Застосуноком користуються понад 100 000 людей, його рекомендують психологи й коучі. Rosebud не замінює терапію. Базове використання безкоштовне; Rosebud Bloom коштує $12,99 на місяць або $107,99 на рік, є безкоштовний пробний період і знижки для студентів та людей з інвалідністю.', 'Rosebud combines journaling, habit-building and emotional support. You write or dictate your thoughts, and AI asks follow-up questions, helps you make sense of your emotions, remembers past entries and finds patterns and new insights about you in them. Data is encrypted in transit and at rest. More than 100,000 people use the app, and psychologists and coaches recommend it. Rosebud does not replace therapy. Basic use is free; Rosebud Bloom costs $12.99 a month or $107.99 a year, with a free trial and student and disability discounts.', 'AI-щоденник з уточнювальними запитаннями
Закономірності й інсайти з ваших записів
Формування звичок
Шифрування даних', 'AI journal with follow-up questions
Patterns and insights from your entries
Habit-building
Data encryption', 'Люди, які ведуть щоденник і працюють над особистим розвитком та емоційним станом.', 'People who journal and work on personal growth and emotional wellbeing.', 'web,mobile', 'none', 'published', 0, 'found', @uid, '2026-10-01 00:00:00' FROM DUAL WHERE @new = 1;
