INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Interior AI', NULL, 'https://interiorai.com', NULL, NULL, 'AI-редизайн інтер''єру за фото: завантажте кімнату, оберіть один з 55+ стилів і за ~25 секунд отримайте фотореалістичний варіант, а також віртуальний стейджинг.', 'AI interior redesign from a photo: upload a room, pick one of 55+ styles and get a photorealistic redesign in about 25 seconds, plus virtual staging.', 'Interior AI перетворює фото кімнати на новий дизайн. Завантажте зображення, оберіть тип приміщення (понад 30) і стиль (понад 55) — і приблизно за 25 секунд отримаєте фотореалістичний варіант інтер''єру. Сервіс також робить віртуальний стейджинг порожніх приміщень, перетворює ескізи й файли SketchUp на реалістичні візуалізації, створює 3D-прогулянки й відео та працює із зовнішнім простором і садом. Його створив інді-розробник Пітер Левелс. Тарифи при річній оплаті: Pro — $349 на рік (1 000 дизайнів); Premium — $599 на рік (5 000 дизайнів, інструменти редагування); Ultra — $1 199 на рік (25 000 дизайнів, пріоритетна швидкість); помісячно — $49, $99 і $199.', 'Interior AI turns a photo of a room into a new design. Upload an image, choose a room type (30+) and a style (55+), and in about 25 seconds you get a photorealistic redesign. It also does virtual staging of empty rooms, turns sketches and SketchUp files into realistic renders, creates 3D walkthroughs and videos, and works with exteriors and gardens. It was built by indie developer Pieter Levels. Plans billed yearly: Pro — $349 a year (1,000 designs); Premium — $599 a year (5,000 designs, editing tools); Ultra — $1,199 a year (25,000 designs, priority speed); monthly — $49, $99 and $199.', 'Редизайн кімнати за фото в 55+ стилях
Віртуальний стейджинг порожніх приміщень
Ескізи й SketchUp у фотореалістичні візуалізації
3D-прогулянки та дизайн саду', 'Room redesign from a photo in 55+ styles
Virtual staging of empty rooms
Sketches and SketchUp to photorealistic renders
3D walkthroughs and garden design', 'Власники житла, дизайнери інтер''єру й ріелтори.', 'Homeowners, interior designers and real estate agents.', 'web', 'none', 'published', 0, 'found', @uid, '2026-10-01 00:00:00' FROM DUAL WHERE @new = 1;
