SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'planner5d.com' OR LOWER(`name`) = LOWER('Planner 5D'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Planner 5D', NULL, 'https://planner5d.com', NULL, NULL, 'Онлайн-планувальник дому й інтер''єру в 2D і 3D з AI: розпізнавання планування з фото, AI Studio для концепцій і рендерів; веб, iOS, Android, Windows і macOS.', 'An online home and interior planner in 2D and 3D with AI: floor plan recognition from photos and AI Studio for concepts and renders; web, iOS, Android, Windows and macOS.', 'Planner 5D дає змогу спланувати квартиру, будинок чи окрему кімнату без спеціальних навичок. У 2D малюють планування, а в 3D розставляють меблі й оздоблення з великої бібліотеки. AI розпізнає план з фото й перетворює його на редагований 3D-проєкт, а AI Studio допомагає з концепціями, візуалізаціями та презентаціями для клієнтів. Є спільна робота в реальному часі. Сервісом користуються понад 120 млн людей — від власників житла до дизайнерів і архітекторів. Тарифи: Free; Premium — $19,99 на місяць або $59,99 на рік; Professional — $49,99 на місяць або $399,99 на рік; Enterprise — за запитом.', 'Planner 5D lets you plan an apartment, house or single room without special skills. You draw the layout in 2D and place furniture and finishes from a large library in 3D. AI recognises a floor plan from a photo and turns it into an editable 3D project, while AI Studio helps with concepts, renders and client presentations. Real-time collaboration is supported. More than 120 million people use it — from homeowners to designers and architects. Plans: Free; Premium — $19.99 a month or $59.99 a year; Professional — $49.99 a month or $399.99 a year; Enterprise on request.', 'Планування в 2D і 3D
AI-розпізнавання плану з фото
AI Studio: концепції, рендери, презентації
Веб, iOS, Android, Windows і macOS', '2D and 3D planning
AI floor plan recognition from photos
AI Studio: concepts, renders, presentations
Web, iOS, Android, Windows and macOS', 'Власники житла, які планують ремонт, а також дизайнери інтер''єру й архітектори.', 'Homeowners planning a renovation, plus interior designers and architects.', 'web,mobile,desktop', 'none', 'published', 0, 'found', @uid, '2026-10-01 00:00:00' FROM DUAL WHERE @new = 1;
