-- REimagineHome — Дизайн інтер'єру
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'reimaginehome.ai' OR LOWER(`name`) = LOWER('REimagineHome'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'REimagineHome', NULL, 'https://www.reimaginehome.ai', NULL, NULL, 'AI-візуалізація інтер''єру й екстер''єру за фото: редизайн кімнат, віртуальний стейджинг, ландшафт і видалення об''єктів, з підбором реальних товарів.', 'AI interior and exterior visualisation from photos: room redesigns, virtual staging, landscaping and object removal, with real product discovery.', 'REimagineHome допомагає уявити, як виглядатиме житло після змін, і ухвалити рішення. За фото сервіс робить редизайн кімнат, віртуальний стейджинг, зміни ландшафту та фасаду, прибирає зайві об''єкти й показує реальні товари, які можна купити. Працювати можна в діалозі з AI, використовувати референсні фото й поступово вносити правки, не починаючи заново; для ріелторів є пакетна обробка фото оголошень. Кредити витрачаються лише на генерації, а обговорення ідей безкоштовне. Є 5 безкоштовних дизайнів без картки; платні тарифи Essential (30 кредитів), Pro (200), Advanced (400) і Agency (900) коштують від $14 до $99 на місяць.', 'REimagineHome helps you picture what your home will look like after changes and make decisions. From a photo it creates room redesigns, virtual staging, landscaping and facade changes, removes unwanted objects and shows real products you can buy. You can work in a conversation with AI, use reference photos and make incremental edits without starting over; real estate agents get batch processing of listing photos. Credits are spent only on generations, while discussing ideas is free. There are 5 free designs with no card; the paid Essential (30 credits), Pro (200), Advanced (400) and Agency (900) plans range from $14 to $99 a month.', 'Редизайн інтер''єру й екстер''єру за фото
Віртуальний стейджинг і видалення об''єктів
Діалог з AI та поступові правки
Підбір реальних товарів', 'Interior and exterior redesign from photos
Virtual staging and object removal
Conversational AI and incremental edits
Real product discovery', 'Власники житла, ріелтори та дизайнери.', 'Homeowners, real estate agents and designers.', 'web', 'none', 'published', 0, 'found', @uid, '2026-10-01 00:00:00' FROM DUAL WHERE @new = 1;
