SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'collov.ai' OR LOWER(`name`) = LOWER('Collov AI'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Collov AI', NULL, 'https://collov.ai', NULL, NULL, 'AI-віртуальний стейджинг і дизайн інтер''єру: перетворює порожні кімнати на мебльовані, прибирає меблі, змінює погоду й газон на фото нерухомості.', 'AI virtual staging and interior design: it turns empty rooms into furnished ones, removes furniture and changes weather and lawns in property photos.', 'Collov AI створено насамперед для ринку нерухомості. Сервіс віртуально мебляє порожні кімнати на фото, дозволяє перегенеровувати варіанти без обмежень, прибирати наявні меблі, робити «вечірні» знімки, замінювати газон і покращувати погоду на фото. Старші тарифи додають стейджинг з кількох ракурсів і віртуальні тури, а Enterprise — API. Фото надаються з комерційною ліцензією, без водяних знаків. Тарифи на місяць: Standard — $19 (60 фото-кредитів); Advanced — $49 (150); Premium — $79 (263); Enterprise — $127 (526, API); при річній оплаті — $228, $588, $948 і $1 524.', 'Collov AI is built primarily for real estate. It virtually furnishes empty rooms in photos, lets you regenerate options without limits, remove existing furniture, create twilight shots, replace lawns and improve the weather in photos. Higher plans add multi-angle staging and virtual tours, and Enterprise adds an API. Photos come with a commercial licence and no watermarks. Monthly plans: Standard — $19 (60 photo credits); Advanced — $49 (150); Premium — $79 (263); Enterprise — $127 (526, API); billed annually — $228, $588, $948 and $1,524.', 'Віртуальний стейджинг порожніх кімнат
Видалення меблів, «вечірні» фото, заміна газону
Необмежена перегенерація
Віртуальні тури та API', 'Virtual staging of empty rooms
Furniture removal, twilight shots, lawn replacement
Unlimited regeneration
Virtual tours and API', 'Ріелтори, агенції нерухомості, забудовники й дизайнери інтер''єру.', 'Real estate agents, brokerages, developers and interior designers.', 'web', 'none', 'published', 0, 'found', @uid, '2026-10-01 00:00:00' FROM DUAL WHERE @new = 1;
SET @pid = (SELECT `id` FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'collov.ai' OR LOWER(`name`) = LOWER('Collov AI')) ORDER BY `id` LIMIT 1);
INSERT IGNORE INTO `product_categories` (`product_id`, `category_id`) SELECT @pid, c.`id` FROM `categories` c WHERE @pid IS NOT NULL AND c.`slug` = 'my-home' LIMIT 1;
INSERT IGNORE INTO `product_subcategories` (`product_id`, `subcategory_id`) SELECT @pid, s.`id` FROM `subcategories` s JOIN `categories` c ON c.`id` = s.`category_id` WHERE @pid IS NOT NULL AND c.`slug` = 'my-home' AND s.`slug` = 'interior-design' LIMIT 1;
INSERT IGNORE INTO `product_translations` (`product_id`, `field_name`, `lang`, `translated_text`, `source`) SELECT @pid, 'short_description', 'en', 'AI virtual staging and interior design: it turns empty rooms into furnished ones, removes furniture and changes weather and lawns in property photos.', 'manual' FROM DUAL WHERE @new = 1;
INSERT IGNORE INTO `product_translations` (`product_id`, `field_name`, `lang`, `translated_text`, `source`) SELECT @pid, 'full_description', 'en', 'Collov AI is built primarily for real estate. It virtually furnishes empty rooms in photos, lets you regenerate options without limits, remove existing furniture, create twilight shots, replace lawns and improve the weather in photos. Higher plans add multi-angle staging and virtual tours, and Enterprise adds an API. Photos come with a commercial licence and no watermarks. Monthly plans: Standard — $19 (60 photo credits); Advanced — $49 (150); Premium — $79 (263); Enterprise — $127 (526, API); billed annually — $228, $588, $948 and $1,524.', 'manual' FROM DUAL WHERE @new = 1;
INSERT IGNORE INTO `product_translations` (`product_id`, `field_name`, `lang`, `translated_text`, `source`) SELECT @pid, 'main_features', 'en', 'Virtual staging of empty rooms
Furniture removal, twilight shots, lawn replacement
Unlimited regeneration
Virtual tours and API', 'manual' FROM DUAL WHERE @new = 1;
